def token_count(lane=LANE):
    text = (Path(lane)/'cycle2'/'tokens'/'COUNT').read_text().strip()
    if text not in ('0','1','2'):
        raise ValueError('COUNT is not an integer in0..2')
    return int(text)


def _argmax():
    mib = (ctypes.c_int*2)(1,8)  # CTL_KERN,KERN_ARGMAX
    value,size = ctypes.c_int(),ctypes.c_size_t(ctypes.sizeof(ctypes.c_int))
    if LIBC.sysctl(mib,2,ctypes.byref(value),ctypes.byref(size),None,0) != 0 or not (0 < value.value <= 16*1024**2):
        raise OSError(ctypes.get_errno(),'KERN_ARGMAX unavailable')
    return value.value


def _argv(pid,capacity):
    mib = (ctypes.c_int*3)(1,49,pid)  # CTL_KERN,KERN_PROCARGS2
    buf,size = ctypes.create_string_buffer(capacity),ctypes.c_size_t(capacity)
    if LIBC.sysctl(mib,3,buf,ctypes.byref(size),None,0) != 0:
        raise OSError(ctypes.get_errno(),'process argv unavailable')
    raw = buf.raw[:size.value]
    if len(raw) < 5:
        raise ValueError('short argv response')
    argc = struct.unpack_from('=i',raw)[0]
    if not (0 < argc <= 100000):
        raise ValueError('invalid argc')
    pos = raw.find(b'\0',4)
    if pos < 0:
        raise ValueError('unterminated executable path')
    while pos < len(raw) and raw[pos] == 0:
        pos += 1
    args = []
    for _ in range(argc):
        end = raw.find(b'\0',pos)
        if end < 0:
            raise ValueError('truncated argv')
        args.append(raw[pos:end])
        pos = end+1
    return args


def lane_rss(lane=LANE,group=None,owner=None):
    """Known same-euid research argv processes only; group monitor separately catches any forbidden setuid member.
    Control-plane/setuid monitoring helpers are not treated as zero-RSS lane members: an explicit128MiB margin is
    reserved. Unknown argv/probes among candidate same-euid processes fail closed; exited/zombie races are skipped.
    """
    sup = supervisor()
    capacity,needle = _argmax(),os.fsencode(str(Path(lane).resolve()))
    total,current,members = 0,0,[]
    for pid in sup.list_pids(4,os.geteuid()):  # PROC_UID_ONLY: never infer ownership from a process's name
        try:
            args = _argv(pid,capacity)
        except (OSError,ValueError):
            state,_,_ = sup.probe(pid)
            if state in ('gone','zombie'):
                continue
            raise
        if not any(needle in arg for arg in args):
            continue
        state,rss,ident = sup.probe(pid)
        if state in ('gone','zombie'):
            continue
        if state != 'alive' or rss <= 0:
            raise RuntimeError('unknown RSS for candidate lane pid%d' % pid)
        total += rss
        if pid == owner or group is not None and ident.get('pgid') == group:
            current += rss
        members.append({'pid':pid,'rss_bytes':rss,'pgid':ident.get('pgid'),'start':ident.get('start')})
    return {'known':True,'rss_bytes':total,'current_group_and_owner_bytes':current,'members':members,
            'scope':'same-euid argv contains absolute lane; no environment data;128MiB control-plane margin'}


def _json_bytes(value):
    return (json.dumps(value,indent=1)+'\n').encode()


def create_census(lane=LANE):
    """An exact allocated/logical census. Unknown/error never becomes a fresh success record."""
    started = time.monotonic()
    data = ACCOUNT.account(lane)
    if data.get('known') is not True or data.get('stat_errors') or type(data.get('new_data_usage_upper_bytes')) is not int:
        raise RuntimeError('exact lane data census unknown: '+repr(data.get('stat_errors')))
    record = {'schema':'PA19-ALLOCATED-CENSUS-v3','started_monotonic':started,'finished_monotonic':time.monotonic(),
              'host_clock':time.strftime('%Y-%m-%dT%H:%M:%S%z'),'data':data,'ttl_seconds':CENSUS_TTL}
    folder = Path(lane)/'cycle2'/'accounting-v3'; folder.mkdir(parents=True,exist_ok=True)
    path = folder/('census-%d-%d.json' % (os.getpid(),time.time_ns()))
    raw = _json_bytes(record)
    with path.open('xb') as f: f.write(raw)
    return {'path':str(path.relative_to(Path(lane))),'sha256':hashlib.sha256(raw).hexdigest()}


def census_for_gate(reference,force=False,lane=LANE):
    if not isinstance(reference,dict): raise ValueError('missing chunk census authority')
    path = Path(lane)/reference['path']
    if not path.resolve().is_relative_to((Path(lane)/'cycle2/accounting-v3').resolve()): raise ValueError('census path outside owned census directory')
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != reference['sha256']: raise ValueError('census SHA differs')
    record = json.loads(raw)
    if record.get('schema') != 'PA19-ALLOCATED-CENSUS-v3' or record.get('ttl_seconds') != CENSUS_TTL: raise ValueError('unknown census schema/TTL')
    data = record.get('data') or {}
    if data.get('known') is not True or data.get('stat_errors') or type(data.get('new_data_usage_upper_bytes')) is not int: raise ValueError('unknown cached census')
    age = time.monotonic()-record['finished_monotonic']
    if age < 0: raise ValueError('future census clock')
    if force or age > CENSUS_TTL:
        return census_for_gate(create_census(lane),False,lane)
    return {'reference':reference,'age_seconds':age,'finished_monotonic':record['finished_monotonic'],
            'current_data_upper_bytes':data['new_data_usage_upper_bytes'],'record':record}


def binary_observations(authority):
    """Expected identities are supplied only by the frozen contract, NEVER promoted from these observations."""
    if not isinstance(authority,dict) or set(authority) != {'python','solver','checker'}: raise ValueError('missing binary authorities')
    observed = {}
    for kind,item in authority.items():
        p,h = item['path'],item['sha256']
        if not isinstance(h,str) or len(h) != 64 or any(c not in '0123456789abcdef' for c in h): raise ValueError('invalid frozen binary SHA')
        if kind == 'python' and p != os.path.abspath(__import__('sys').executable): raise ValueError('unexpected Python binary path')
        if kind == 'solver' and p not in ('/opt/homebrew/bin/kissat','/opt/homebrew/bin/cadical'): raise ValueError('unexpected solver path')
        if kind == 'checker' and p != str(LANE/'tools/drat-trim/drat-trim'): raise ValueError('unexpected checker path')
        actual = digest(p)
        observed[kind] = {'path':p,'expected_sha256':h,'observed_sha256':actual,'matches':actual == h}
    return observed


def full_gate(lease,phase,lane=LANE,providers=None):
    """Last operation before every admission. Expensive census refresh precedes final fresh guards/hash checks."""
    p,errors = providers or {},[]
    accounting,rss,binaries,count,free,required = None,{'known':False},{},None,None,None
    try:
        accounting = p['census']() if 'census' in p else census_for_gate(lease['census_reference'],bool(lease.get('force_census_refresh')),lane)
        lease['census_reference'] = accounting['reference']
        lease['force_census_refresh'] = False
        bound = lease['whole_plan_remaining_bound_bytes']
        if type(bound) is not int or bound < ALL_PLANNED_RETAINED_BOUND: errors.append('whole-plan bound missing/narrowed')
        if type(accounting.get('current_data_upper_bytes')) is not int or accounting['current_data_upper_bytes'] < 0: errors.append('unknown allocated-data bytes')
        elif accounting['current_data_upper_bytes']+bound+OTHER_WRITER_MARGIN > DATA_CAP: errors.append('allocated-data cap with whole-plan reservation/margin')
        if not (0 <= accounting['age_seconds'] <= CENSUS_TTL): errors.append('stale/unknown census age')
        rss = p['rss']() if 'rss' in p else lane_rss(lane,os.getpgrp() if phase != 'construct' else None,lease['owner_pid'])
        if not isinstance(rss,dict) or rss.get('known') is not True or type(rss.get('rss_bytes')) is not int or rss['rss_bytes'] < 0:
            errors.append('unknown RSS/headroom')
        else:
            if lease['group_rss_cap_bytes'] != GROUP_RSS_CAP or lease['busy_units'] != 2 or lease['lane_busy_ceiling'] != 4:
                errors.append('wrong normal resource budget')
            current = rss.get('current_group_and_owner_bytes')
            if type(current) is not int or not (0 <= current <= rss['rss_bytes']): errors.append('unknown current-group RSS')
            elif rss['rss_bytes']+max(0,GROUP_RSS_CAP-current)+CONTROL_MARGIN > LANE_CAP: errors.append('RSS headroom')
            members = rss.pop('members',None)
            if members is not None:
                rss['member_count'] = len(members)
                rss['member_set_sha256'] = hashlib.sha256(json.dumps(members,sort_keys=True).encode()).hexdigest()
        # Frozen expected identities survive every capacity wait; compare again immediately before every spawn.
        binaries = p['binaries']() if 'binaries' in p else binary_observations(lease['binary_authority'])
        if set(binaries) != {'python','solver','checker'} or any(v.get('matches') is not True for v in binaries.values()): errors.append('contract binary drift')
        count = p['count']() if 'count' in p else token_count(lane)
        if type(count) is not int or not (0 <= count <= 2): errors.append('COUNT ceiling/format')
        if count == 0 and phase != 'checker': errors.append('new admissions paused')
        if _CANCEL[0]: errors.append('owner cancelled')
        for name in ADMISSION_MARKERS:
            if (Path(lane)/'cycle2'/name).exists(): errors.append('STOP/veto '+name)
        growth = lease['projected_growth_bytes']
        if type(growth) is not int or growth < ITEM_GROWTH: errors.append('unknown/narrow projected retained growth')
        required = BASE_GATE+growth
        free = p['free']() if 'free' in p else (lambda s:s.f_bavail*s.f_frsize)(os.statvfs(lane))
        if type(free) is not int or free < required: errors.append('fresh statvfs growth/floor gate')
        cut = lease.get('admission_cutoff_epoch')  # v6_3 frozen policy clock, independent of STOP markers
        wallclock = p['wallclock']() if 'wallclock' in p else time.time()
        if type(cut) not in (int,float) or not math.isfinite(cut): errors.append('frozen policy admission cutoff missing')
        elif wallclock >= cut: errors.append('admission closed by frozen policy clock')
        now = p['clock']() if 'clock' in p else time.monotonic()
        allowance = 1450 if phase == 'checker' else 2200
        if now+allowance > lease['chunk_deadline_monotonic'] or now+allowance > lease['item_deadline_monotonic']: errors.append('deadline allowance')
        # Record the age at actual admission, not merely at cache loading before other guards.
        if 'census' not in p:
            accounting['age_seconds'] = time.monotonic()-accounting['finished_monotonic']
            if accounting['age_seconds'] > CENSUS_TTL: errors.append('census expired before admission')
    except (OSError,ValueError,KeyError,TypeError,RuntimeError,AssertionError) as exc:
        errors.append('gate measurement/authority error: '+repr(exc))
    return {'phase':phase,'at_monotonic':time.monotonic(),'at_epoch':time.time(),'admission_cutoff_epoch':lease.get('admission_cutoff_epoch'),'count':count,'free_bytes':free,'required_free_bytes':required,
        'rss':rss,'binary_observations':binaries,'census':accounting,'whole_plan_remaining_bound_bytes':lease.get('whole_plan_remaining_bound_bytes'),
        'other_writer_margin_bytes':OTHER_WRITER_MARGIN,'additional_data_cap_bytes':DATA_CAP,'group_rss_cap_bytes':GROUP_RSS_CAP,
        'busy_units':2,'lane_busy_ceiling':4,'projected_growth_bytes':lease.get('projected_growth_bytes'),
        'chunk_deadline_monotonic':lease.get('chunk_deadline_monotonic'),'item_deadline_monotonic':lease.get('item_deadline_monotonic'),
        'next_phase_allowance_seconds':1450 if phase == 'checker' else 2200,'errors':errors,'admitted':not errors}


class Capacity:
    """One normal token. NO automatic tier2 path. Every stop requires a complete receipt/parent decision."""
    def __init__(self,deadline,lane=LANE,metadata=False,wait_allowance=2550):
        self.lane,self.deadline,self.metadata,self.wait_allowance = Path(lane),deadline,metadata,wait_allowance
        self.fds,self.safe,self.record,self.children = [],True,None,[]
        self.settlement = None

    def __enter__(self):
        started = time.monotonic()
        try:
            while not self.fds:
                if _CANCEL[0] or time.monotonic()+self.wait_allowance > self.deadline: raise RuntimeError('capacity wait deadline/cancellation')
                n = token_count(self.lane)
                if n == 0: raise RuntimeError('COUNT0; no new admission')
                for i in range(n):
                    fd = os.open(self.lane/'cycle2/tokens'/('t%d' % i),os.O_RDWR)
                    try: fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
                    except BlockingIOError:
                        os.close(fd); continue
                    self.fds.append(fd)
                    os.ftruncate(fd,0)
                    os.write(fd,('%d %.3f supervised-v3\n' % (os.getpid(),time.time())).encode())
                    break
                if not self.fds: time.sleep(0.1)
            self.wait_seconds = time.monotonic()-started
            return self
        except BaseException:
            self._release(); raise

    def supervise(self,command,name,lease,record,quarantine):
        assert not self.metadata and len(self.fds) == 1
        s = supervisor()
        lease['force_census_refresh'] = bool(lease.get('force_census_refresh') or self.wait_seconds > CENSUS_TTL)
        gate = full_gate(lease,'worker',self.lane)
        if gate['admitted'] and self.deadline-time.monotonic() < 2400:  # v6_3: budget must fit the frozen native end
            gate['errors'].append('group budget 2400 s does not fit before the chunk deadline'); gate['admitted'] = False
        if not gate['admitted']: return None,gate
        self.safe = False
        try:
            rec = s.supervise(command,name,2400,GROUP_RSS_CAP,FLOOR,str(self.lane),str(record),str(quarantine),
                              grace=60,owner_child=self.children)
            self.record = rec
            if rec.get('observed_signal'): _CANCEL[0] = True  # v6_3: never swallow an outer cancellation
            self._settle(rec)
            return rec,gate
        except BaseException:
            if self.record is None:
                self._freeze('supervisor raised without an ownership record')
                while True: time.sleep(1)
            self._settle(self.record)
            raise

    def _freeze(self,why):
        try:
            with (self.lane/'cycle2/tokens/COUNT').open('w') as f: f.write('0\n')
        except BaseException: pass
        try:
            with (self.lane/'cycle2/m2k3-QUARANTINE.flag').open('x') as f:
                json.dump({'status':'UNKNOWN','reason':why,'owner_pid':os.getpid()},f)
        except BaseException: pass

    def _live(self,s,leader,observed):
        live = s.live_members(leader,s.probe,observed)
        for text,ident in observed.items():
            state,_,current = s.probe(int(text))
            if state == 'unknown' or state == 'alive' and (not ident.get('start') or current.get('start') == ident.get('start')):
                live.append({'pid':int(text),'state':state})
        return live

    def _settle(self,rec):
        s = supervisor()
        if rec.get('leader_pid') is None and not self.children:
            self.safe = True
            self.settlement = {'no_child_started':True,'group_quiescent':True,'leader_reaped':True}
            return
        if len(self.children) != 1 or self.children[0].pid != rec.get('leader_pid'):
            self._freeze('owned Popen handle unavailable/mismatched; do not guess reaping')
            while True: time.sleep(1)
        child,leader = self.children[0],rec['leader_pid']
        observed = dict(rec.get('observed_identities') or {})
        stop = rec.get('stop') or {}
        if rec.get('uncertain') or rec.get('quarantine_record') or rec.get('cleanup_exception') or stop.get('survivors') or stop.get('killpg_error'):
            self._freeze('nonclean group cleanup; retain token through explicit leader wait and group quiescence')
        polls = 0
        while True:
            try:
                live = self._live(s,leader,observed)
                child.poll(); polls += 1
                if not live and child.returncode is not None:
                    returncode = child.wait()  # exact retained Popen, also for leaders exiting AFTER the grace
                    after = self._live(s,leader,observed)
                    if not after:
                        self.settlement = {'group_quiescent':True,'leader_reaped':True,'owned_leader_pid':leader,
                            'leader_returncode':returncode,'explicit_owned_popen_wait':True,'poll_calls':polls,
                            'post_reap_quiescence_monotonic':time.monotonic()}
                        self.safe = True
                        return
            except BaseException: self._freeze('settlement probe/reap failed; token stays held')
            time.sleep(0.25)

    def _release(self):
        for fd in reversed(self.fds):
            fcntl.flock(fd,fcntl.LOCK_UN); os.close(fd)
        self.fds = []

    def __exit__(self,*exc):
        if not self.safe:
            self._freeze('owner exit before known quiescence/reaping')
            if self.record is None:
                while True: time.sleep(1)
            self._settle(self.record)
        self._release()

#!/usr/bin/env python3
"""Supervised per-item native core. NO token/bigmem ownership or /bin/ps helper inside this group.
Owner holds capacity and the reviewed supervise_r3 controls the entire process group on every exceptional exit.
Same B constructor, Kissat/CaDiCaL limits, staged binary DRAT zstd1/raw1200MiB/compressed500MiB as the old protocol;
new successful-write/close measurements for BOTH CNF feeds, exact completed collectors, and persistent INVALID class.
No regular-file CNF/proof retention. Native stdout is hashed; only bounded solver text/status lines are retained.
"""
import errno
import hashlib
import json
import os
import subprocess
import sys
import threading
import time
from compression import zstd
from pathlib import Path

import encode_skel_b as ENC
import m2_supervised_runtime_v6_3 as R

L = Path(__file__).resolve().parent.parent
CHUNK = 1 << 20
MAX_RAW = 1200*1024**2
MAX_ZBUF = 500*1024**2
FEED_SETTLE_SECONDS = 30  # feeders poll stop every <=10ms on nonblocking FIFOs; longer means lifecycle failure
KISSAT,CADICAL,DT = '/opt/homebrew/bin/kissat','/opt/homebrew/bin/cadical',str(L/'tools/drat-trim/drat-trim')
P0 = [4,3,3,3,3,3]


class BoundedUnknown(Exception):
    pass


def status_lines(raw):
    return [v.decode('ascii','backslashreplace') for v in raw.replace(b'\r',b'').split(b'\n') if v.startswith(b's ')]


def collector(stream,record,retain=False):
    h,n,line,out = hashlib.sha256(),0,bytearray(),bytearray()
    lines,error,eof,overline = [],None,False,False
    def endline():
        nonlocal overline
        if line.startswith(b's '):
            if overline: raise ValueError('overlong native status line')
            if len(lines) >= 16: raise ValueError('bounded native status-line count exceeded')
            lines.append(bytes(line).decode('ascii','backslashreplace'))
        line.clear()
        overline = False
    try:
        while True:
            b = stream.read(65536)
            if not b:
                eof = True
                break
            h.update(b)
            n += len(b)
            if retain:
                if len(out)+len(b) > 2*1024**2: raise ValueError('bounded solver stdout capture exceeded')
                out.extend(b)
            parts = b.replace(b'\r',b'').split(b'\n')
            for k,part in enumerate(parts):
                if len(line)+len(part) > 4096:
                    overline = True
                line.extend(part[:max(0,4096-len(line))])
                if k != len(parts)-1: endline()
        if line: endline()
    except BaseException as exc:
        error = repr(exc)
    finally:
        try: stream.close()
        except BaseException as exc: error = error or repr(exc)
        record.update(bytes_read=n,sha256=h.hexdigest(),status_lines=lines,error=error,complete=bool(eof and error is None))
        if retain: record['text'] = bytes(out).decode('utf-8','replace')


def feed_cnf(path,data,record,stop,deadline):
    """Count/hash ONLY successful writes; require close success. Provenance separates bound-induced cancellation
    (pipeline stop event or item deadline) from real open/write/close transport failures."""
    fd,h,n,error,closed,cancelled,close_error = None,hashlib.sha256(),0,None,False,None,None
    def cancel_reason():
        if stop.is_set(): return 'stop-event'
        if time.monotonic() > deadline: return 'item-deadline'
        return None
    try:
        while fd is None:
            cancelled = cancel_reason()
            if cancelled: raise TimeoutError('CNF FIFO open cancelled: '+cancelled)
            try: fd = os.open(path,os.O_WRONLY|os.O_NONBLOCK)
            except OSError as exc:
                if exc.errno != errno.ENXIO: raise
                time.sleep(0.01)
        view = memoryview(data)
        while n < len(view):
            cancelled = cancel_reason()
            if cancelled: raise TimeoutError('CNF write cancelled: '+cancelled)
            try: wrote = os.write(fd,view[n:n+CHUNK])
            except BlockingIOError:
                time.sleep(0.01)
                continue
            if wrote <= 0: raise OSError('zero/negative CNF write')
            h.update(view[n:n+wrote])
            n += wrote
    except BaseException as exc:
        error = repr(exc)
    finally:
        if fd is not None:
            try:
                os.close(fd)
                closed = True
            except BaseException as exc:
                close_error = repr(exc)
                error = error or close_error
        record.update(bytes=n,sha256=h.hexdigest(),error=error,close_ok=closed,opened=fd is not None,
                      cancelled=cancelled if error is not None else None,close_error=close_error,
                      complete=bool(n == len(data) and closed and error is None))


def proof_reader(path,state,stop):
    h,n,zparts,zbytes,error,eof = hashlib.sha256(),0,[],0,None,False
    cap = None
    zc = zstd.ZstdCompressor(level=1)
    try:
        with open(path,'rb',buffering=0) as f:
            while True:
                b = f.read(CHUNK)
                if not b:
                    eof = True
                    break
                if cap: continue
                h.update(b)
                n += len(b)
                z = zc.compress(b)
                if z: zparts.append(z); zbytes += len(z)
                if n > MAX_RAW or zbytes > MAX_ZBUF:
                    cap = 'raw' if n > MAX_RAW else 'zbuf'
                    state['proof_cap_hit'] = cap
                    state.update(raw_bytes=n,raw_sha256=h.hexdigest(),compressed_bytes=zbytes,
                                 count_scope='hashed retained prefix through cap; later drained bytes not counted')
                    stop.set()
            if not cap:
                tail = zc.flush()
                if zbytes+len(tail) > MAX_ZBUF:
                    cap = 'zbuf-tail'
                    state['proof_cap_hit'] = cap
                    state.update(raw_bytes=n,raw_sha256=h.hexdigest(),compressed_bytes=zbytes,
                                 count_scope='complete raw stream; rejected compressed-frame tail not retained')
                    stop.set()
                else:
                    zparts.append(tail)
                    zbytes += len(tail)
    except BaseException as exc:
        error = repr(exc)
        state.update(raw_bytes=n,raw_sha256=h.hexdigest(),compressed_bytes=zbytes,reader_error=error,reader_complete=False)
        stop.set()
    state.update(raw_bytes=n,raw_sha256=h.hexdigest(),compressed_bytes=zbytes,chunks=zparts,
                 reader_error=error,reader_complete=bool(eof and error is None and cap is None))


def replay(parts,stream,record):
    h,n,error,complete,closed = hashlib.sha256(),0,None,False,False
    zd = zstd.ZstdDecompressor()
    try:
        for part in parts:
            raw = zd.decompress(part)
            view,offset = memoryview(raw),0
            while offset < len(view):
                wrote = stream.write(view[offset:offset+CHUNK])
                if wrote is None or wrote <= 0: raise OSError('incomplete proof pipe write')
                h.update(view[offset:offset+wrote])
                offset += wrote
                n += wrote
        if not zd.eof or zd.unused_data:
            raise ValueError('incomplete/extra zstd frame')
        complete = True
    except BaseException as exc:
        error = repr(exc)
    finally:
        try: stream.close(); closed = True
        except BaseException as exc: error = error or repr(exc)
        record.update(bytes=n,sha256=h.hexdigest(),error=error,close_ok=closed,complete=bool(complete and closed and error is None))


def start_native(command,collect,retain,stdin=False,start_hook=None):
    p = subprocess.Popen(command,stdin=subprocess.PIPE if stdin else subprocess.DEVNULL,stdout=subprocess.PIPE,
                         stderr=subprocess.STDOUT,bufsize=0)
    if start_hook is not None: start_hook(p)  # control harness only; production never supplies it
    t = threading.Thread(target=collector,args=(p.stdout,collect,retain),daemon=True)
    t.start()
    return p,t


def await_native(p,seconds,stop):
    end = time.monotonic()+seconds+60
    while p.poll() is None:
        if stop.is_set(): raise BoundedUnknown('declared proof cap/reader stop')
        if time.monotonic() > end: raise BoundedUnknown('native wall/grace bound')
        time.sleep(0.02)
    return p.returncode


def outcome(result):
    """Failed certification is scientific UNKNOWN. Independently ESTABLISHED transport corruption is evaluated FIRST
    and keeps a persistent INVALID integrity veto even with checker TIMEOUT, bounded stops or caps. Incomplete proof
    replay after an exact checker TIMEOUT is expected interruption; a completed mismatching delivery is not.
    """
    def unknown(reason,invalid=False,halt=False,sat=False,chunk_stop=False):
        return {'status':'UNKNOWN','integrity_status':'INVALID' if invalid else 'NOT_EVALUATED',
                'integrity_errors':[reason] if invalid else [],'unknown_reason':reason,
                'sat_candidate':sat,'halt_production':bool(halt or invalid or sat),'chunk_stop':bool(chunk_stop or halt or invalid or sat)}
    sc,dc = result.get('solver_collector',{}),result.get('checker_collector',{})
    if result.get('solver_rc') == 10 or sc.get('status_lines') == ['s SATISFIABLE']:
        return unknown('unverified SAT candidate',sat=True)
    if any('NOT VERIFIED' in str(v) for v in dc.get('status_lines',[])):
        return unknown('checker NOT VERIFIED',invalid=True)
    if dc.get('complete') and dc.get('status_lines') not in (['s VERIFIED'],['s TIMEOUT']):
        return unknown('unexpected/duplicate/missing checker verdict',invalid=True)
    expected_bytes,expected_sha = result.get('cnf_bytes'),result.get('cnf_sha256')
    feeds,p,r = result.get('cnf_feeds',{}),result.get('proof_stream',{}),result.get('proof_delivery',{})
    for name,feed in feeds.items():
        n = feed.get('bytes')
        if type(n) is int and type(expected_bytes) is int and n > expected_bytes:
            return unknown('CNF feed exceeded exact formula bytes: '+name,invalid=True)
        if feed.get('complete') and (n != expected_bytes or feed.get('sha256') != expected_sha):
            return unknown('completed CNF delivery differs from pinned formula: '+name,invalid=True)
        if feed.get('close_error'):
            return unknown('CNF FIFO close failed: '+name,invalid=True)
        if feed.get('error') is not None and feed.get('cancelled') not in ('stop-event','item-deadline'):
            return unknown('CNF transport failure (not bound-induced cancellation): '+name,invalid=True)
    if p.get('reader_error'):
        return unknown('proof reader error',invalid=True)
    if r.get('complete') and (r.get('bytes') != p.get('raw_bytes') or r.get('sha256') != p.get('raw_sha256')):
        return unknown('completed proof replay differs from streamed proof',invalid=True)
    if type(r.get('bytes')) is int and type(p.get('raw_bytes')) is int and not p.get('proof_cap_hit') and r['bytes'] > p['raw_bytes']:
        return unknown('proof replay exceeded streamed proof',invalid=True)
    if result.get('lifecycle_error'):
        return unknown('incomplete native lifecycle: '+str(result['lifecycle_error']),invalid=True)
    if result.get('resource_refusal'):
        return unknown('worker solver/checker/preconstruction admission refused; recorded UNKNOWN, no persistent HALT',chunk_stop=True)
    if result.get('proof_integrity_error') or result.get('input_integrity_error'):
        return unknown('input/proof transport integrity failure',invalid=True)
    if result.get('proof_cap_hit'):
        return unknown('declared proof cap; not certified')
    if result.get('bounded_unknown'):
        return unknown('bounded native stop')
    if sc.get('error') or not sc.get('complete'):
        return unknown('solver collector incomplete/failed',invalid=True)
    sf = feeds.get('solver',{})
    if sf.get('error') or not sf.get('complete') or not sf.get('close_ok') or sf.get('bytes') != expected_bytes or sf.get('sha256') != expected_sha:
        return unknown('solver CNF delivery incomplete',invalid=True)
    rc,s = result.get('solver_rc'),sc.get('status_lines')
    if rc == 0 and s in ([],['s UNKNOWN']):
        return unknown('solver native limit/UNKNOWN')
    if rc != 20 or s != ['s UNSATISFIABLE']:
        return unknown('solver did not self-exit20 with exact UNSAT verdict',invalid=True)
    if set(feeds) != {'solver','checker'}:
        return unknown('both CNF feeds required',invalid=True)
    if not p.get('reader_complete'):
        return unknown('proof reader incomplete before checker stage',invalid=True)
    cf = feeds['checker']
    checker_feed_exact = bool(cf.get('complete') and cf.get('close_ok') and cf.get('error') is None and cf.get('bytes') == expected_bytes and cf.get('sha256') == expected_sha)
    if dc.get('complete') and dc.get('error') is None and dc.get('status_lines') == ['s TIMEOUT']:
        if not checker_feed_exact:
            return unknown('checker CNF feed not exact under TIMEOUT; corruption cannot be excluded',invalid=True)
        return unknown('checker native timeout; incomplete proof replay is expected interruption')
    if not checker_feed_exact:
        return unknown('checker CNF write/close/bytes/SHA failure',invalid=True)
    if result.get('checker_rc') != 0 or not dc.get('complete') or dc.get('error') or dc.get('status_lines') != ['s VERIFIED']:
        return unknown('checker did not self-exit0 with exact VERIFIED verdict',invalid=True)
    if not r.get('complete') or r.get('error') or not r.get('close_ok') or r.get('bytes') != p.get('raw_bytes') or r.get('sha256') != p.get('raw_sha256'):
        return unknown('proof replay/decompression/close incomplete or mismatched',invalid=True)
    return {'status':'UNSAT','integrity_status':'VALIDATED','integrity_errors':[],'sat_candidate':False,'halt_production':False}


def pipeline(raw,job,commands=None,start_hook=None):
    """commands/start_hook are library-only controlled fixtures; the production CLI supplies neither."""
    result = {'schema':'PA19-NATIVE-RESULT-v6_3','cnf_sha256':hashlib.sha256(raw).hexdigest(),'cnf_bytes':len(raw),
              'cnf_feeds':{'solver':{},'checker':{}},'solver_collector':{},'checker_collector':{},
              'proof_stream':{},'proof_delivery':{},'gates':[],'no_regular_cnf_or_proof':True}
    folder = Path(job['workdir'])
    assert folder.resolve().is_relative_to(L.resolve()), 'native I/O escapes owned lane'
    folder.mkdir(parents=True,exist_ok=False)
    paths = {k:str(folder/k) for k in ('solver-cnf.fifo','checker-cnf.fifo','proof.fifo')}
    for p in paths.values(): os.mkfifo(p,0o600)
    stop,threads,feeders = threading.Event(),[],[]
    s = job['solver_seconds']
    native = [KISSAT,'-q','-f','--seed=1','--time=%d' % s] if job['solver'] == 'kissat' else [CADICAL,'-q','-t',str(s)]
    solver_command = native+[paths['solver-cnf.fifo'],paths['proof.fifo']]
    checker_command = [DT,paths['checker-cnf.fifo'],'-i','-t',str(job['checker_seconds'])]
    if commands is not None: solver_command,checker_command = commands(paths)
    result.update(solver_command=solver_command,checker_command=checker_command)
    try:
        sf = threading.Thread(target=feed_cnf,args=(paths['solver-cnf.fifo'],raw,result['cnf_feeds']['solver'],stop,job['lease']['item_deadline_monotonic']),daemon=True)
        pr = threading.Thread(target=proof_reader,args=(paths['proof.fifo'],result['proof_stream'],stop),daemon=True)
        sf.start(); threads.append(sf); feeders.append(('solver',sf))
        pr.start(); threads.append(pr)
        t0 = time.monotonic()
        gate = R.full_gate(job['lease'],'solver')
        result['gates'].append(gate)
        if not gate['admitted']: result['resource_refusal'] = gate['errors']; return result
        sp,st = start_native(solver_command,result['solver_collector'],True,start_hook=start_hook)
        threads.append(st)
        result['solver_rc'] = await_native(sp,s,stop)
        result['solver_stop'] = 'self'
        result['solve_seconds'] = time.monotonic()-t0
        for t in (sf,pr,st): t.join(60)
        if any(t.is_alive() for t in (sf,pr,st)): raise RuntimeError('solver feed/proof/collector thread incomplete')
        if result['proof_stream'].get('proof_cap_hit'):
            result['proof_cap_hit'] = result['proof_stream']['proof_cap_hit']
            return result
        sc = result['solver_collector']
        if result['solver_rc'] != 20 or sc.get('status_lines') != ['s UNSATISFIABLE'] or not sc.get('complete') or sc.get('error'):
            return result
        if result['cnf_feeds']['solver'].get('bytes') != len(raw) or not result['cnf_feeds']['solver'].get('complete'):
            result['input_integrity_error'] = 'solver CNF delivery incomplete'
            return result
        if not result['proof_stream'].get('reader_complete') or result['proof_stream'].get('reader_error'):
            result['proof_integrity_error'] = 'solver proof stream incomplete/failed'
            return result
        cf = threading.Thread(target=feed_cnf,args=(paths['checker-cnf.fifo'],raw,result['cnf_feeds']['checker'],stop,job['lease']['item_deadline_monotonic']),daemon=True)
        t1 = time.monotonic()
        gate = R.full_gate(job['lease'],'checker')
        result['gates'].append(gate)
        if not gate['admitted']: result['resource_refusal'] = gate['errors']; return result
        dp,dt = start_native(checker_command,result['checker_collector'],False,stdin=True,start_hook=start_hook)
        threads.append(dt)
        cf.start(); threads.append(cf); feeders.append(('checker',cf))
        rp = threading.Thread(target=replay,args=(result['proof_stream']['chunks'],dp.stdin,result['proof_delivery']),daemon=True)
        rp.start(); threads.append(rp)
        result['checker_rc'] = await_native(dp,job['checker_seconds'],threading.Event())
        result['checker_stop'] = 'self'
        result['check_seconds'] = time.monotonic()-t1
        for t in (cf,rp,dt): t.join(60)
        if any(t.is_alive() for t in (cf,rp,dt)): raise RuntimeError('checker feed/replay/collector thread incomplete')
    except BoundedUnknown as exc:
        result['bounded_unknown'] = str(exc)
        result['proof_cap_hit'] = result['proof_stream'].get('proof_cap_hit')
    except BaseException as exc:
        result['lifecycle_error'] = repr(exc)
    finally:
        stop.set()
        # Settle EVERY started CNF feeder before freezing observations: a real failure published after the stop
        # must still be classified. An unsettled feeder is an explicit lifecycle/integrity failure, never UNKNOWN.
        unsettled = []
        for name,thread in feeders:
            thread.join(FEED_SETTLE_SECONDS)
            if thread.is_alive(): unsettled.append(name)
        result['feeders_settled'] = [name for name,_ in feeders if name not in unsettled]
        if unsettled:
            result['feeders_unsettled'] = unsettled
            result['lifecycle_error'] = result.get('lifecycle_error') or 'CNF feeder did not settle after stop: '+','.join(unsettled)
        # Freeze public metrics away from any non-feeder daemon that is still unwinding after a failure.
        result['proof_stream'] = {k:v for k,v in result['proof_stream'].items() if k != 'chunks'}
        result['solver_collector'] = dict(result['solver_collector'])
        result['checker_collector'] = dict(result['checker_collector'])
        result['cnf_feeds'] = {k:dict(v) for k,v in result['cnf_feeds'].items()}
        result['proof_delivery'] = dict(result['proof_delivery'])
        result.update(outcome(result))
        if not result.get('sat_candidate') and result['integrity_status'] != 'INVALID':
            result['solver_collector'].pop('text',None)
        if result['status'] == 'UNSAT' and len((json.dumps(result,indent=1)+'\n').encode()) > 32768:
            result.update(status='UNKNOWN',halt_production=True,metadata_bound_error='ordinary worker receipt exceeds32KiB')
    return result


def recipe_cnf(job):
    recipe = job['recipe']
    sp = L/recipe['skeleton_path']
    assert R.digest(sp) == recipe['skeleton_sha256'] and R.digest(L/'src'/'encode_skel_b.py') == recipe['encoder_sha256']
    D = json.loads(sp.read_bytes())
    sk = D['skeletons'][recipe['b_index']]
    special = [p for p in D['profiles'] if list(p) != P0]
    if recipe['mode'] == 'direct':
        nv,cl = ENC.build_v2(D['c0'],[tuple(t) for t in sk['types']],sk['empty'],special)
    elif recipe['mode'] == 'partbatch':
        ep = L/recipe['list_path']
        assert R.digest(ep) == recipe['list_sha256']
        ed = json.loads(ep.read_bytes())
        assert ed['num_placements'] == len(ed['placements']) == recipe['complete_denominator'] > 0
        lo,hi = recipe['indices']
        nv,cl = ENC.build_partbatch(D['c0'],[tuple(t) for t in sk['types']],sk['empty'],special,[ed['placements'][i] for i in range(lo,hi+1)])
    else: raise ValueError('unknown production recipe')
    raw = ENC.cnf_bytes(nv,cl)
    assert len(raw) == job['cnf_bytes'] and hashlib.sha256(raw).hexdigest() == job['cnf_sha256'],'owner/worker construction differs'
    return raw


def main():
    path,h = Path(sys.argv[1]),sys.argv[2]
    assert R.digest(path) == h
    job = json.loads(path.read_bytes())
    assert job['schema'] == 'PA19-NATIVE-JOB-v6_3' and job['solver'] in ('kissat','cadical')
    assert job['checker_seconds'] == 1200 and job['solver_seconds'] in (300,600)
    assert os.getppid() == job['lease']['owner_pid'] == int(os.environ['K3_SUPERVISOR_PID'])
    assert os.environ['K3_SUPERVISOR_SCRIPT'] == str(R.SUP_PATH) and R.digest(R.SUP_PATH) == R.SUP_SHA
    assert job['binary_authority'] == job['lease']['binary_authority']
    assert all(x['matches'] for x in R.binary_observations(job['binary_authority']).values())
    assert job['binary_authority']['solver']['path'] == (KISSAT if job['solver'] == 'kissat' else CADICAL)
    assert job['binary_authority']['checker']['path'] == DT
    assert Path(job['result_path']).parent.resolve().is_relative_to(L.resolve())
    for rel,expected in job['source_sha256'].items():
        assert not Path(rel).is_absolute() and (L/rel).resolve().is_relative_to(L.resolve())
        assert R.digest(L/rel) == expected, 'worker source changed: '+rel
    try:
        pre = R.full_gate(job['lease'],'construct')
        if not pre['admitted']:
            result = {'schema':'PA19-NATIVE-RESULT-v6_3','resource_refusal':pre['errors'],'worker_preconstruction_gate':pre}
            result.update(outcome(result))
        else:
            raw = recipe_cnf(job)
            result = pipeline(raw,job)
            result['worker_preconstruction_gate'] = pre
    except BaseException as exc:
        result = {'schema':'PA19-NATIVE-RESULT-v6_3','status':'UNKNOWN','integrity_status':'INVALID','integrity_errors':[repr(exc)],
                  'sat_candidate':False,'halt_production':True,'construction_error':repr(exc)}
    payload = (json.dumps(result,indent=1)+'\n').encode()
    assert len(payload) <= 16*1024**2, 'halting worker diagnostic bound'
    temporary = job['result_path']+'.writing'
    with open(temporary,'xb') as f:
        f.write(payload)
    os.link(temporary,job['result_path'])  # primary appears only after the complete worker JSON closes
    print(json.dumps({k:result.get(k) for k in ('status','halt_production','solve_seconds','check_seconds','bounded_unknown','lifecycle_error')}),flush=True)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Fail-closed proof-flag/input-identity primitives for the new ms09 full-B inventory.
Only explicitly known staged schemas11..15 are supported; there is NO unknown-revision fallback, empty-cover
acceptance or SAT-to-UNSAT inference. Mathematical input SHA is provided by the frozen constructor recipe/pin
and is independently recomputable. Calibration proof validity is separate from parent permission to consume it.
"""
import hashlib
import json
import re
from pathlib import Path

SHA = re.compile(r'[0-9a-f]{64}\Z')
KNOWN_STAGED = (11,12,13,14,15)
KISSAT = '/opt/homebrew/bin/kissat'
CADICAL = '/opt/homebrew/bin/cadical'


def digest(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def is_int(v):
    return type(v) is int


def proof_errors(r,expected):
    if not isinstance(r,dict):
        return ['record is not an object']
    if not isinstance(expected,dict) or not all(is_int(expected.get(k)) for k in ('multiset','b_index','native_limit','cnf_bytes')):
        return ['expected formula identity/counts are missing or not integers']
    ei = expected.get('indices')
    if ei is not None and not (isinstance(ei,list) and len(ei) == 2 and all(is_int(v) for v in ei) and 0 <= ei[0] <= ei[1]):
        return ['expected interval is not a valid exact integer pair']
    if not isinstance(expected.get('cnf_sha256'),str) or SHA.fullmatch(expected['cnf_sha256']) is None or expected['cnf_bytes'] <= 0:
        return ['expected numeric formula SHA/size is invalid']
    e = []
    def need(ok,message):
        if not ok:
            e.append(message)
    need(is_int(r.get('stream_check_revision')) and r['stream_check_revision'] in KNOWN_STAGED,'unsupported/missing staged revision')
    need(r.get('staged') is True,'not a staged record')
    need(r.get('status') == 'UNSAT','not UNSAT (SAT is a veto, UNKNOWN stays open)')
    need(is_int(r.get('solver_rc')) and r['solver_rc'] == 20 and r.get('solver_stop') == 'self','solver did not self-exit20')
    for key in ('checked','drat_trim_verified','reader_ok','replay_ok','replay_sha256_matches'):
        need(r.get(key) is True,'required true flag: '+key)
    for key in ('checker_interrupted','aborted_by_sigterm'):
        need(r.get(key) is False,'required false flag: '+key)
    need(not r.get('admission_denied') and not r.get('proof_cap_hit'),'admission refusal/proof cap')
    need('lratstrict_verified' not in r,'lratstrict-only/mixed record not eligible')
    need(r.get('drat_trim_binary') == 'tools/drat-trim/drat-trim','wrong native checker identity')
    dt = r.get('drat_trim') or {}
    need(isinstance(dt,dict) and type(dt.get('rc')) is int and dt['rc'] == 0 and dt.get('stop') == 'self','drat-trim did not self-exit0')
    need(isinstance(dt,dict) and dt.get('s_lines') == ['s VERIFIED'] and dt.get('says_verified') is True,'checker verdict not exactly s VERIFIED')
    n = r.get('drat_bytes')
    ph = r.get('drat_sha256')
    need(is_int(n) and n >= 0 and isinstance(ph,str) and SHA.fullmatch(ph) is not None,'invalid streamed proof count/SHA')
    replay = r.get('replay') or {}
    need(isinstance(replay,dict) and replay.get('ok') is True and replay.get('error') is None,'replay failed/missing')
    need(isinstance(replay,dict) and is_int(replay.get('bytes')) and replay['bytes'] == n and replay.get('sha256') == ph,'delivered proof bytes/SHA differ')
    need(isinstance(r.get('cnf_sha256'),str) and SHA.fullmatch(r['cnf_sha256']) is not None,'invalid CNF SHA')
    need(r.get('cnf_sha256') == expected.get('cnf_sha256'),'CNF SHA not exact expected formula')
    need(is_int(r.get('cnf_bytes')) and r['cnf_bytes'] == expected.get('cnf_bytes') and r['cnf_bytes'] > 0,'CNF byte count differs')
    for key in ('multiset','b_index'):
        need(is_int(r.get(key)) and r[key] == expected[key],'identity differs: '+key)
    need(r.get('encoder') == expected['encoder'],'wrong encoder identity')
    idx = expected.get('indices')
    if idx is None:
        need('indices' not in r,'direct record unexpectedly names a subcase')
        need(r.get('generator') == 'gen_skel_b.py','direct generator differs')
    else:
        need(isinstance(r.get('indices'),list) and len(r['indices']) == 2 and all(is_int(v) for v in r['indices']) and r['indices'] == idx,'wrong batch indices')
    limit = expected['native_limit']
    tail = '; binary DRAT staged (zstd-1 in memory) then drat-trim -i -t 1200'
    kline = '%s -q -f --seed=1 --time=%d CNF PROOF%s' % (KISSAT,limit,tail)
    cline = '%s -q -t %d CNF PROOF%s' % (CADICAL,limit,tail)
    allowed = [kline] if expected.get('kissat_only') else [kline,cline]
    need(r.get('solver') in allowed,'solver command/limit differs')
    info = r.get('solver_info') or {}
    target_info = {'version':'kissat 4.0.4 (/opt/homebrew/bin/kissat)','seed':'--seed=1'} if r.get('solver') == kline else {'version':'cadical 3.0.1 (/opt/homebrew/bin/cadical)','seed':'default (no --seed option given)'}
    need(info == target_info and r.get('check_budget') == 1200,'solver version/seed/check budget differs')
    return e


def inspect(path,expected,frozen_sha=None):
    p = Path(path)
    try: raw = p.read_bytes()
    except FileNotFoundError: return {'state':'MISSING','errors':['missing required record'],'sat':False}
    except OSError as exc: return {'state':'INTEGRITY_VETO','errors':['unreadable record: '+repr(exc)],'sat':False}
    h = hashlib.sha256(raw).hexdigest()
    try: r = json.loads(raw)
    except (ValueError,UnicodeError) as exc:
        return {'state':'INTEGRITY_VETO','errors':['invalid JSON: '+repr(exc)],'sha256':h,'sat':False}
    if not isinstance(r,dict):
        return {'state':'INTEGRITY_VETO','errors':['record is not an object'],'sha256':h,'sat':False,'record':r}
    inner = r.get('native_result') if isinstance(r.get('native_result'),dict) else {}
    sat = r.get('sat_candidate') is True or inner.get('sat_candidate') is True or r.get('status') == 'SAT' or inner.get('status') == 'SAT'
    if r.get('pipeline_schema') == 'PA19-SUPERVISED-DRAT-v6_3':
        import m2_supervised_evidence_v6_3 as supervised
        errors = supervised.identity_errors(r,expected)
        checker = inner.get('checker_collector') if isinstance(inner.get('checker_collector'),dict) else {}
        invalid = r.get('integrity_status') == 'INVALID' or inner.get('integrity_status') == 'INVALID' or any('NOT VERIFIED' in str(v) for v in checker.get('status_lines',[]))
        if errors or invalid:
            if invalid: errors.append('persistent INVALID integrity/verdict veto; scientific result UNKNOWN')
            state = 'INTEGRITY_VETO'
        elif r.get('halt_production') or r.get('safety_veto') or inner.get('halt_production'):
            errors.append('persistent supervisor/worker safety hold')
            state = 'HALT_UNKNOWN'
        elif r.get('status') == 'UNKNOWN':
            state = 'UNQUALIFIED'
        else:
            if not expected.get('lane_root'): errors.append('explicit owned input root required')
            else: errors += supervised.proof_errors(r,expected,expected['lane_root'])
            state = 'QUALIFIED' if not errors else 'INTEGRITY_VETO'
    elif 'pipeline_schema' in r:
        errors,state = ['unknown pipeline schema; no fallback'],'INTEGRITY_VETO'
    else:
        # Historical classification only; the final component reader never consumes these as measured-v3 evidence.
        errors = proof_errors(r,expected)
        dt = r.get('drat_trim') or {}
        bad = isinstance(dt,dict) and any('NOT VERIFIED' in str(v) for v in dt.get('s_lines',[]))
        state = 'QUALIFIED' if not errors else ('INTEGRITY_VETO' if bad or r.get('checked') is True or r.get('stream_check_revision') not in KNOWN_STAGED else 'UNQUALIFIED')
    if frozen_sha is not None and h != frozen_sha:
        errors.insert(0,'immutable record SHA differs')
        state = 'INTEGRITY_VETO'
    if sat: state = 'SAT_VETO'
    return {'state':state,'errors':errors,'sha256':h,'sat':sat,'record':r}


def expected(mi,bi,indices,cnf_sha,cnf_bytes,encoder='encode_skel_b.build_partbatch',native_limit=600,kissat_only=False):
    return {'multiset':mi,'b_index':bi,'indices':indices,'cnf_sha256':cnf_sha,'cnf_bytes':cnf_bytes,
            'encoder':encoder,'native_limit':native_limit,'kissat_only':kissat_only}

